const chk=[]; const eq=(n,a,b)=>chk.push([n,a===b?'OK':'MISMATCH '+a+' vs '+b]);
// Tolling now supported on ALL fee years: full stream vs window-only risk scenario
eq('fees tolled', 180000+195000+210000+225000+240000, 1050000);
eq('fees risk scenario', 210000+225000+240000, 675000);
// 18% indirect share of full derivative recovery — the offer coincidence
eq('0.18 x 1,050,000', 0.18*1050000, 189000);
eq('gap offer vs indirect', 189100-189000, 100);
eq('0.061 x 1,050,000', 0.061*1050000, 64050);
// Disclosure-trigger rent threshold for the 6% monthly fee
eq('rent needed for 50k/yr', (50000/0.06).toFixed(0), '833333');
// Settlement floor check (broker value, dilution stands)
eq('floor', 0.061*9800000, 597800);
// Cost-adjusted realism band: floor plus tolled fees indirect share at 18%
eq('18pct of tolled fees added to claim value', 189000, 189000);
// Notice lead unchanged
eq('lead days', Math.round((new Date('2026-09-20')-new Date('2026-08-20'))/86400000), 31);
const d=new Date('2026-10-01'); d.setDate(d.getDate()+30);
eq('expiry', d.toISOString().slice(0,10), '2026-10-31');
eq('days left from 10-08', Math.round((new Date('2026-10-31')-new Date('2026-10-08'))/86400000), 23);
// Counter number recheck
eq('ask', 0.18*7200000, 1296000);
JSON.stringify(chk.filter(c=>c[1]!=='OK').length?chk:('ALL '+chk.length+' CHECKS OK'),null,1)

